// Fixed vectors from Bitwarden's GPLv3 bitwarden-crypto tests, not generated by
// this implementation. See THIRD_PARTY_NOTICES.md for the upstream sources.
func TestOfficialKDFVectors(t *testing.T) {
	for _, tc := range []struct {
		kdf  KDF
		want []byte
	}{
		{KDF{Type: 0, Iterations: 10000}, []byte{31, 79, 104, 226, 150, 71, 177, 90, 194, 80, 172, 209, 17, 129, 132, 81, 138, 167, 69, 167, 254, 149, 2, 27, 39, 197, 64, 42, 22, 195, 86, 75}},
		{KDF{Type: 1, Iterations: 4, Memory: 32, Parallelism: 2}, []byte{207, 240, 225, 177, 162, 19, 163, 76, 98, 106, 179, 175, 224, 9, 17, 240, 20, 147, 237, 47, 246, 150, 141, 184, 62, 225, 131, 242, 51, 53, 225, 242}},
	} {
		key, err := DeriveMaster([]byte("67t9b5g67$%Dh89n"), " TEST_KEY ", tc.kdf)
		if err != nil || !bytes.Equal(key, tc.want) {
			t.Fatalf("official KDF vector mismatch: %v", err)
		}
	}
	key, err := DeriveMaster([]byte("asdfasdf"), "test_salt", KDF{Type: 1, Iterations: 4, Memory: 32, Parallelism: 2})
	if err != nil || AuthorizationHash(key, []byte("asdfasdf")) != "PR6UjYmjmppTYcdyTiNbAhPJuQQOmynKbdEl1oyi/iQ=" {
		t.Fatal("official authentication hash mismatch")
	}
}
func TestOfficialHKDFVector(t *testing.T) {
	key, _ := DeriveMaster([]byte("67t9b5g67$%Dh89n"), "test_key", KDF{Type: 0, Iterations: 10000})
	got, err := StretchMaster(key)
	want := []byte{111, 31, 178, 45, 238, 152, 37, 114, 143, 215, 124, 83, 135, 173, 195, 23, 142, 134, 120, 249, 61, 132, 163, 182, 113, 197, 189, 204, 188, 21, 237, 96, 221, 127, 206, 234, 101, 27, 202, 38, 86, 52, 34, 28, 78, 28, 185, 16, 48, 61, 127, 166, 209, 247, 194, 87, 232, 26, 48, 85, 193, 249, 179, 155}
	if err != nil || !bytes.Equal(got, want) {
		t.Fatal("HKDF must expand the PRK separately with enc and mac")
	}
}
func TestKDFRejectsUnsafeParameters(t *testing.T) {
	for _, kdf := range []KDF{{Type: 2, Iterations: 600000}, {Type: 0, Iterations: 1}, {Type: 0, Iterations: 2000001}, {Type: 1, Iterations: 1, Memory: 32, Parallelism: 4}, {Type: 1, Iterations: 3, Memory: 1025, Parallelism: 4}, {Type: 1, Iterations: 3, Memory: 64, Parallelism: 256}} {
		if _, err := DeriveMaster([]byte("password"), "test@example.invalid", kdf); err != vaulterr.ErrKDF {
			t.Fatalf("unbounded KDF accepted: %+v", kdf)
		}
	}
}

func FuzzDecryptNeverPanics(f *testing.F) {
	f.Add("2.bad|input|tag")
	f.Add("")
	f.Add("7.AAAA")
	f.Fuzz(func(t *testing.T, value string) { _, _ = DecryptString(value, make([]byte, 64)) })
}
